import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';

class BasicCachedImageExample extends StatelessWidget {
  const BasicCachedImageExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('캐시 이미지 기본')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 가장 기본적인 사용법
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/300/200',
              width: 300,
              height: 200,
              fit: BoxFit.cover,
            ),

            const SizedBox(height: 24),

            // 플레이스홀더와 에러 위젯 포함
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/300/200',
              width: 300,
              height: 200,
              fit: BoxFit.cover,

              // 로딩 중 표시
              placeholder: (context, url) => Container(
                color: Colors.grey.shade200,
                child: const Center(
                  child: CircularProgressIndicator(),
                ),
              ),

              // 에러 시 표시
              errorWidget: (context, url, error) => Container(
                color: Colors.grey.shade200,
                child: const Icon(
                  Icons.error,
                  color: Colors.red,
                  size: 40,
                ),
              ),
            ),

            const SizedBox(height: 24),

            // 진행률 표시
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/300/200',
              width: 300,
              height: 200,
              fit: BoxFit.cover,

              // 다운로드 진행률 표시
              progressIndicatorBuilder: (context, url, progress) {
                return Center(
                  child: CircularProgressIndicator(
                    value: progress.progress,  // 0.0 ~ 1.0
                  ),
                );
              },

              errorWidget: (context, url, error) => const Icon(Icons.error),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';

class AdvancedCachedImageExample extends StatelessWidget {
  const AdvancedCachedImageExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('캐시 이미지 활용')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 1. 원형 프로필 이미지
            const Text('원형 프로필 이미지', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            ClipOval(
              child: CachedNetworkImage(
                imageUrl: 'https://i.pravatar.cc/150',
                width: 80,
                height: 80,
                fit: BoxFit.cover,
                placeholder: (context, url) => Container(
                  color: Colors.grey.shade300,
                  child: const Icon(Icons.person, size: 40),
                ),
                errorWidget: (context, url, error) => Container(
                  color: Colors.grey.shade300,
                  child: const Icon(Icons.person, size: 40),
                ),
              ),
            ),

            const SizedBox(height: 24),

            // 2. 둥근 모서리 카드 이미지
            const Text('둥근 모서리 카드', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            ClipRRect(
              borderRadius: BorderRadius.circular(12),
              child: CachedNetworkImage(
                imageUrl: 'https://picsum.photos/400/200',
                width: double.infinity,
                height: 200,
                fit: BoxFit.cover,
                placeholder: (context, url) => Container(
                  color: Colors.grey.shade200,
                  child: const Center(child: CircularProgressIndicator()),
                ),
                errorWidget: (context, url, error) => Container(
                  color: Colors.grey.shade200,
                  child: const Icon(Icons.broken_image, size: 50),
                ),
              ),
            ),

            const SizedBox(height: 24),

            // 3. 페이드 인 애니메이션 커스터마이징
            const Text('커스텀 페이드 애니메이션', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/400/200',
              width: double.infinity,
              height: 200,
              fit: BoxFit.cover,

              // 페이드 인 시간 조절
              fadeInDuration: const Duration(milliseconds: 500),
              fadeOutDuration: const Duration(milliseconds: 200),

              // 페이드 인 곡선
              fadeInCurve: Curves.easeIn,

              placeholder: (context, url) => Container(
                color: Colors.grey.shade200,
              ),
              errorWidget: (context, url, error) => const Icon(Icons.error),
            ),

            const SizedBox(height: 24),

            // 4. HTTP 헤더 추가 (인증 등)
            const Text('HTTP 헤더 포함', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/400/200',
              width: double.infinity,
              height: 200,
              fit: BoxFit.cover,

              // 인증 헤더 추가
              httpHeaders: const {
                'Authorization': 'Bearer your_token_here',
                'Custom-Header': 'value',
              },

              placeholder: (context, url) => const Center(
                child: CircularProgressIndicator(),
              ),
              errorWidget: (context, url, error) => const Icon(Icons.error),
            ),

            const SizedBox(height: 24),

            // 5. 메모리 최적화 (큰 이미지 리사이징)
            const Text('메모리 최적화', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/1200/800',  // 큰 원본 이미지
              width: 200,
              height: 150,
              fit: BoxFit.cover,

              // 메모리에 캐시할 크기 제한 (원본보다 작게)
              memCacheWidth: 400,
              memCacheHeight: 300,

              placeholder: (context, url) => Container(
                color: Colors.grey.shade200,
              ),
              errorWidget: (context, url, error) => const Icon(Icons.error),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:cached_network_image/cached_network_image.dart';
