class ImageProviderExample extends StatelessWidget {
  const ImageProviderExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('ImageProvider 사용')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 1. Container 배경 이미지
            const Text('Container 배경', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            Container(
              width: double.infinity,
              height: 200,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(12),
                image: const DecorationImage(
                  image: CachedNetworkImageProvider(
                    'https://picsum.photos/800/400',
                  ),
                  fit: BoxFit.cover,
                ),
              ),
              child: const Center(
                child: Text(
                  '배경 이미지',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                    shadows: [Shadow(blurRadius: 10)],
                  ),
                ),
              ),
            ),

            const SizedBox(height: 24),

            // 2. CircleAvatar
            const Text('CircleAvatar', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            const CircleAvatar(
              radius: 50,
              backgroundImage: CachedNetworkImageProvider(
                'https://i.pravatar.cc/200',
              ),
            ),

            const SizedBox(height: 24),

            // 3. Ink.image (Material ripple 효과와 함께)
            const Text('Ink.image (터치 효과)', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            Material(
              child: Ink.image(
                image: const CachedNetworkImageProvider(
                  'https://picsum.photos/400/200',
                ),
                width: double.infinity,
                height: 150,
                fit: BoxFit.cover,
                child: InkWell(
                  onTap: () {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('이미지 탭됨!')),
                    );
                  },
                ),
              ),
            ),

            const SizedBox(height: 24),

            // 4. FadeInImage와 함께 (추가 페이드 효과)
            const Text('FadeInImage', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            FadeInImage(
              placeholder: const AssetImage('assets/placeholder.png'),
              image: const CachedNetworkImageProvider(
                'https://picsum.photos/400/200',
              ),
              width: double.infinity,
              height: 150,
              fit: BoxFit.cover,
              fadeInDuration: const Duration(milliseconds: 300),
              imageErrorBuilder: (context, error, stackTrace) {
                return Container(
                  width: double.infinity,
                  height: 150,
                  color: Colors.grey.shade200,
                  child: const Icon(Icons.error),
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';
import 'package:flutter_cache_manager/flutter_cache_manager.dart';

// 커스텀 캐시 매니저 정의
class CustomCacheManager {
  static const key = 'customCacheKey';

  static CacheManager instance = CacheManager(
    Config(
      key,
      stalePeriod: const Duration(days: 7),  // 캐시 유효 기간
      maxNrOfCacheObjects: 100,  // 최대 캐시 파일 수
      repo: JsonCacheInfoRepository(databaseName: key),
      fileService: HttpFileService(),
    ),
  );
}

class CacheManagementExample extends StatefulWidget {
  const CacheManagementExample({super.key});

  @override
  State<CacheManagementExample> createState() => _CacheManagementExampleState();
}

class _CacheManagementExampleState extends State<CacheManagementExample> {
  String _cacheInfo = '캐시 정보 로딩 중...';

  @override
  void initState() {
    super.initState();
    _loadCacheInfo();
  }

  Future<void> _loadCacheInfo() async {
    // 기본 캐시 매니저의 캐시 경로
    final cacheManager = DefaultCacheManager();
    final cacheDir = await cacheManager.store.fileDir;

    setState(() {
      _cacheInfo = '캐시 경로: $cacheDir';
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('캐시 관리')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // 캐시 정보 표시
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text('캐시 정보', style: TextStyle(fontWeight: FontWeight.bold)),
                    const SizedBox(height: 8),
                    Text(_cacheInfo, style: const TextStyle(fontSize: 12)),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 16),

            // 기본 캐시 매니저 사용
            const Text('기본 캐시', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/400/200?default',
              height: 150,
              fit: BoxFit.cover,
              placeholder: (context, url) => const Center(
                child: CircularProgressIndicator(),
              ),
              errorWidget: (context, url, error) => const Icon(Icons.error),
            ),

            const SizedBox(height: 24),

            // 커스텀 캐시 매니저 사용
            const Text('커스텀 캐시 (7일 유효)', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            CachedNetworkImage(
              imageUrl: 'https://picsum.photos/400/200?custom',
              height: 150,
              fit: BoxFit.cover,
              cacheManager: CustomCacheManager.instance,  // 커스텀 캐시 매니저
              placeholder: (context, url) => const Center(
                child: CircularProgressIndicator(),
              ),
              errorWidget: (context, url, error) => const Icon(Icons.error),
            ),

            const SizedBox(height: 24),

            // 캐시 관리 버튼들
            ElevatedButton(
              onPressed: () async {
                // 특정 URL의 캐시 삭제
                await DefaultCacheManager().removeFile(
                  'https://picsum.photos/400/200?default',
                );
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('해당 이미지 캐시 삭제됨')),
                );
              },
              child: const Text('특정 이미지 캐시 삭제'),
            ),

            const SizedBox(height: 12),

            ElevatedButton(
              onPressed: () async {
                // 전체 캐시 삭제
                await DefaultCacheManager().emptyCache();
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('전체 캐시 삭제됨')),
                );
              },
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
              child: const Text('전체 캐시 삭제'),
            ),

            const SizedBox(height: 12),

            ElevatedButton(
              onPressed: () async {
                // 이미지 미리 캐싱
                await precacheImage(
                  const CachedNetworkImageProvider(
                    'https://picsum.photos/800/600',
                  ),
                  context,
                );
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('이미지 미리 캐싱 완료')),
                );
              },
              child: const Text('이미지 미리 캐싱'),
            ),
          ],
        ),
      ),
    );
  }
}

